const REPO='justappgrabbin/Stellarproximology-lab';
const BASE=`https://github.com/${REPO}`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const workflow=(name)=>`${BASE}/actions/workflows/${name}.yml`;
const link=(name,label)=>`<a class="button secondary" href="${workflow(name)}" target="_blank" rel="noopener noreferrer">${label}</a>`;
export function evolutionView(noteCount=0){return `<div class="page-head"><div><div class="eyebrow">BUILD & EVOLVE</div><h1>Let the app grow with you.</h1><p class="head-description">Prepare a change. Review the evidence. Approve the exact version.</p></div><a class="button secondary" href="${BASE}/pulls" target="_blank" rel="noopener noreferrer">Review pull requests</a></div><div class="three-grid"><section class="card"><div class="eyebrow">01 · PREPARE</div><h2>Research a need</h2><p class="muted">The workflow reads app source and prepares a candidate. No code is pushed or executed at this stage.</p>${link('evolution-propose','Open candidate workflow')}</section><section class="card"><div class="eyebrow">02 · YOUR APPROVAL</div><h2>Push & check</h2><p class="muted">Review the candidate and enter its SHA-256 in GitHub. An isolated branch gets a draft PR and checks.</p>${link('evolution-push','Approve a candidate push')}</section><section class="card"><div class="eyebrow">03 · YOUR APPROVAL</div><h2>Apply the version</h2><p class="muted">After checks pass, review the diff and approve the exact commit. Changed code requires new approval.</p>${link('evolution-merge','Approve a checked merge')}</section></div><div class="bottom-grid"><section class="card"><div class="card-title"><h2>What should grow next?</h2><span class="pill">Private draft</span></div><label for="evolution-need">A need or improvement to investigate</label><textarea class="search" id="evolution-need" maxlength="3000" rows="5" placeholder="For example: I need a clearer way to compare practitioner notes across sessions."></textarea><p class="notice">There are ${noteCount} reflections in this workspace. They stay private; only the text you explicitly enter here is included in the shareable brief.</p><div class="row"><button class="button" id="save-evolution-brief">Download build brief</button><button class="button secondary" id="show-github-request">Preview GitHub request</button></div><div id="github-request-preview"></div></section><section class="card"><div class="card-title"><h2>Version-bound approval</h2><span class="pill">Owner controlled</span></div><p class="muted">GitHub verifies the personal approver as <strong>justappgrabbin</strong>. A checkbox in this app cannot authorize repository writes.</p><p class="muted">Weekly research is opt-in. It can prepare candidates, but every push and merge needs your approval. Main, model publishing, and deployment never update on a schedule.</p><a class="link-button" href="${BASE}/blob/main/README.md" target="_blank" rel="noopener noreferrer">Setup and recovery instructions</a><p class="notice">Workflows become available after the setup PR is merged. AI generation requires EVOLUTION_MODEL and EVOLUTION_HF_TOKEN. Until configured, research produces an honest setup report.</p></section></div><section class="card" style="margin-top:24px"><div class="card-title"><h2>GitHub run history</h2><button class="button secondary" id="refresh-evolution">Refresh status</button></div><div id="evolution-status" class="muted">Load recent runs to see completed work or a specific failure. GitHub is the source of truth.</div></section>`;}
export function bindEvolution(){const field=document.querySelector('#evolution-need');if(!field)return;try{field.value=localStorage.getItem('synthia-evolution-need')||'';}catch{}field.addEventListener('input',()=>{try{localStorage.setItem('synthia-evolution-need',field.value);}catch{}});document.querySelector('#save-evolution-brief').onclick=()=>{const text=field.value.trim();if(!text){field.setCustomValidity('Describe the need first.');field.reportValidity();return;}field.setCustomValidity('');const blob=new Blob([JSON.stringify({schema:1,repository:REPO,need:text,approval:'Candidate preparation only. Push and merge need separate GitHub owner approval.',createdAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='synthia-build-brief.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};document.querySelector('#show-github-request').onclick=()=>{const text=field.value.trim();const el=document.querySelector('#github-request-preview');if(!text){el.textContent='Describe a need first.';return;}const body=`## Need\n${text}\n\n## Approval scope\nPrepare a reviewed candidate. Do not push changes to main or deploy without my separate approval.\n\nNo charts or reflection history were attached automatically.`;const url=`${BASE}/issues/new?title=${encodeURIComponent('Evolution request: '+text.slice(0,70))}&body=${encodeURIComponent(body)}`;el.innerHTML=`<p class="notice">Only this draft text will be included in the GitHub issue editor. This repository is public. Review it before submitting.</p><pre class="text-block" style="overflow-wrap:anywhere">${esc(body)}</pre><a class="button secondary" href="${url}" target="_blank" rel="noopener noreferrer">Open GitHub issue editor</a>`;};document.querySelector('#refresh-evolution').onclick=async()=>{const el=document.querySelector('#evolution-status');el.textContent='Loading GitHub run history…';try{const response=await fetch(`https://api.github.com/repos/${REPO}/actions/runs?per_page=12`,{headers:{Accept:'application/vnd.github+json'},signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error(`GitHub returned ${response.status}`);const result=await response.json();const runs=result.workflow_runs.filter(r=>r.name.startsWith('Evolution'));el.innerHTML=runs.length?runs.map(r=>`<div class="source-row"><div class="source-icon">G</div><div><h3>${esc(r.name)}</h3><p>${esc(r.conclusion||r.status)} · ${esc(r.head_sha.slice(0,10))} · ${esc(new Date(r.created_at).toLocaleString())}</p></div><a class="button secondary" href="${esc(r.html_url)}" target="_blank" rel="noopener noreferrer">Inspect run</a></div>`).join(''):'No evolution runs yet. Merge the setup PR, then run candidate preparation.';}catch(error){el.textContent=`Could not load runs: ${error.message}. Open GitHub Actions to inspect the current status.`;}};}
